<?php
declare(strict_types=1);namespace App\Command;use App\Imperium\Runtime\Mission\BoundedOperationalExecutionService;use Symfony\Component\Console\Attribute\AsCommand;use Symfony\Component\Console\Command\Command;use Symfony\Component\Console\Input\InputArgument;use Symfony\Component\Console\Input\InputInterface;use Symfony\Component\Console\Input\InputOption;use Symfony\Component\Console\Output\OutputInterface;
#[AsCommand(name:'imperium:mission:execute-bounded-iteration',description:'Consume one exact execution authorization and seal one internal cognition output.')]
final class MissionExecuteBoundedIterationCommand extends Command{public function __construct(private readonly BoundedOperationalExecutionService$s){parent::__construct();}protected function configure():void{$this->addArgument('authorization-id',InputArgument::REQUIRED)->addOption('json',null,InputOption::VALUE_NONE);}protected function execute(InputInterface$i,OutputInterface$o):int{try{$r=$this->s->execute((string)$i->getArgument('authorization-id'));}catch(\Throwable$e){$o->writeln('<error>REFUSED</error> '.$e->getMessage());return self::FAILURE;}$o->writeln($i->getOption('json')?json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR):'<info>BOUNDED_EXECUTION_COMPLETED</info> '.$r['execution_id']);return self::SUCCESS;}}
